import{t as e}from"./jsx-runtime-lw2jiZar.js";import{A as t,C as n,E as r,M as i,N as a,O as o,P as s,S as c,T as l,_ as u,b as d,k as f,l as p,n as m,o as h,p as g,t as _,v}from"./shared-DP9JVsk0.js";import{t as y}from"./CodeEditor-BZlrvoTL.js";var b=e();function x({module:e}){return(0,b.jsxs)(a,{children:[(0,b.jsx)(i,{chip:e??`Блок 1 · Первые шаги в Python`,title:`3. Целые числа и деление`,intro:`Свяжем целые значения с их единицами, запишем расчёт и выберем вид деления под нужный ответ.`}),(0,b.jsxs)(s,{number:`00`,title:`От значения к расчёту`,children:[(0,b.jsx)(o,{children:`Мы уже давали значениям имена и встречали целые числа. Теперь научимся считать с ними так, чтобы не путать, что именно показывает ответ. Сначала подпишем числа и разберём простой расчёт. Затем проследим, как меняется значение имени. В конце выберем, что получить при делении: ответ с дробной частью, полные группы или то, что осталось.`}),(0,b.jsx)(f,{variant:`connected`,items:[{title:`Точка старта`,description:`Мы умеем давать значениям имена и записывать их в программе.`},{title:`Новый вопрос`,description:`Как понять, что посчитано, и какой ответ нужен при делении?`},{title:`Результат`,description:`Мы составим расчёт, обновим число и разберём три ответа при делении.`}]}),(0,b.jsx)(`p`,{children:`Можно знать знак операции и всё же получить ответ не о том. Например, число коробок и число книг нельзя просто сложить. Поэтому мы каждый раз будем спрашивать себя: «Что означает это число? Что я хочу узнать?» Так легче выбрать действие и проверить ответ.`})]}),(0,b.jsxs)(s,{number:`01`,title:`Целое число отвечает на вопрос о количестве`,children:[(0,b.jsxs)(o,{children:[`Целое число не содержит дробной части: например, `,(0,b.jsx)(`code`,{children:`0`}),`, `,(0,b.jsx)(`code`,{children:`8`}),` или `,(0,b.jsx)(`code`,{children:`-3`}),`. В Python для таких значений используется тип `,(0,b.jsx)(`code`,{children:`int`}),`. Но число само по себе не объясняет, что мы считаем. `,(0,b.jsx)(`code`,{children:`8`}),` может означать восемь минут, восемь коробок или восемь книг. Слова «минуты» и «книги» называют единицы измерения и помогают понять условие.`]}),(0,b.jsxs)(`p`,{children:[`Если считаем книги, ноль означает, что книг нет. Отрицательное число книг обычно не имеет смысла. Но отрицательная температура или долг вполне возможны. Число `,(0,b.jsx)(`code`,{children:`-3`}),` получает смысл из условия и имени, например `,(0,b.jsx)(`code`,{children:`temperature`}),`: Python сам не знает, что оно означает. При этом `,(0,b.jsx)(`code`,{children:`-3`}),` всё равно остаётся целым числом `,(0,b.jsx)(`code`,{children:`int`}),`; меняется смысл для задачи, а не тип значения.`]}),(0,b.jsx)(`p`,{children:`Подписи помогают проверить действие: книги можно сложить с книгами, а коробки нельзя просто сложить с книгами. Python разрешит сложить числа, поэтому единицы ответа проверяем мы сами. Если единицы разные, сначала нужно объяснить правило перевода: например, сколько минут составляют час.`}),(0,b.jsxs)(`p`,{children:[`Одинаковое значение может отвечать на разные вопросы: `,(0,b.jsx)(`code`,{children:`books = 8`}),` и `,(0,b.jsx)(`code`,{children:`minutes = 8`}),`хранят восьмёрку, но обозначают разное. Имя помогает человеку понять число, а при выводе единицу нужно назвать отдельно.`]}),(0,b.jsx)(g,{prompt:`Соединим имя с тем, что оно считает.`,leftTitle:`Имя и значение`,rightTitle:`Смысл для человека`,pairs:[{left:`books = 8`,right:`8 книг`},{left:`minutes = 8`,right:`8 минут`},{left:`temperature = -3`,right:`температура ниже нуля`}],explanation:`Имя связывает число с ситуацией: books = 8 означает 8 книг, а minutes = 8 означает 8 минут. Само значение int единицу не хранит. Поэтому Python выполнит даже сложение несвязанных величин, а единицу ответа и подходящее правило перевода проверяем мы.`})]}),(0,b.jsxs)(s,{number:`02`,title:`Составляем выражение по смыслу`,children:[(0,b.jsxs)(`p`,{children:[`Сложение `,(0,b.jsx)(`code`,{children:`+`}),` объединяет количества с одинаковой единицей, вычитание `,(0,b.jsx)(`code`,{children:`-`}),` показывает остаток или разницу, а умножение `,(0,b.jsx)(`code`,{children:`*`}),` считает одинаковые группы. Три группы по четыре можно записать как `,(0,b.jsx)(`code`,{children:`4 + 4 + 4`}),` или короче как `,(0,b.jsx)(`code`,{children:`3 * 4`}),`. Если в группах разное число предметов, посчитаем их отдельно и сложим.`]}),(0,b.jsxs)(`p`,{children:[`На трёх полках по четыре книги, ещё две лежат отдельно. На полках `,(0,b.jsx)(`code`,{children:`3 * 4 = 12`}),` книг; вместе с отдельными будет `,(0,b.jsx)(`code`,{children:`12 + 2 = 14`}),` книг. Сначала считаем одинаковые группы, затем объединяем книги с книгами.`]}),(0,b.jsxs)(`p`,{children:[`Математическая запись `,(0,b.jsx)(`code`,{children:`3 * 4 = 12`}),` сообщает равенство. В Python строка`,(0,b.jsx)(`code`,{children:`books_on_shelves = 3 * 4`}),` присваивает результат имени.`]}),(0,b.jsxs)(`p`,{children:[`Для вычитания действует та же проверка: `,(0,b.jsx)(`code`,{children:`12 - 5 = 7`}),` означает, что из 12 книг убрали 5 и осталось 7 книг. Результат сохраняет ту же единицу, что и исходные количества.`]}),(0,b.jsxs)(`p`,{children:[`Python выполняет умножение раньше сложения и вычитания. Поэтому в `,(0,b.jsx)(`code`,{children:`3 * 4 + 2`}),` сначала считаем книги на полках. Скобки задают другой первый шаг, когда слова задачи просят объединить группы.`]}),(0,b.jsx)(`p`,{children:`Слова условия помогают выбрать порядок. «Три полки по четыре книги и ещё две книги отдельно» означает сначала посчитать одинаковые группы, затем добавить книги. Если добавили две полки, а книг на каждой по-прежнему четыре, сначала складываем число полок.`}),(0,b.jsx)(`p`,{children:`До записи формулы назовём каждый вход. Три здесь означает число полок, четыре означает книги на полке, а два означает отдельные книги. Складывать три полки с двумя книгами нельзя: это разные предметы счёта. Умножение сначала превращает число полок и книги на полке в общее количество книг. Теперь результат можно сложить с отдельными книгами. Python выполнит любую допустимую арифметику, но соответствие чисел условию проверяем мы. Имена помогают сохранить этот смысл даже при других данных.`}),(0,b.jsx)(l,{question:`Какое выражение подходит к условию: три полки по четыре книги и две книги отдельно?`,left:{title:`Книги на полках и отдельно`,code:`3 * 4 + 2`,note:`Сначала считаем три одинаковые полки, затем добавляем две книги.`},right:{title:`Пять полок по четыре книги`,code:`(3 + 2) * 4`,note:`Сначала объединяем три полки и ещё две, затем считаем книги на всех пяти.`},preferred:`left`,explanation:`Первое выражение даёт 14 книг. Второе описывает другое условие и даёт 20: оно считает пять полок по четыре книги. Скобки показывают, что сначала складываем число полок.`}),(0,b.jsxs)(`p`,{children:[`Операции одного уровня Python выполняет слева направо: сначала `,(0,b.jsx)(`code`,{children:`+`}),` или `,(0,b.jsx)(`code`,{children:`-`}),` слева, затем следующий. Например, `,(0,b.jsx)(`code`,{children:`10 - 3 - 2`}),` даёт 5, потому что сначала из 10 вычитается 3.`]}),(0,b.jsx)(c,{statement:(0,b.jsxs)(b.Fragment,{children:[`Выражение `,(0,b.jsx)(`code`,{children:`10 - 3 - 2`}),` даёт 9.`]}),isTrue:!1,explanation:`Python считает слева направо: 10 - 3 = 7, затем 7 - 2 = 5. Чтобы сначала вычислить 3 - 2, нужны скобки: 10 - (3 - 2).`}),(0,b.jsx)(u,{code:`shelves = 3
books_per_shelf = 4
loose_books = 2
total_books = shelves * books_per_shelf + loose_books
print(total_books)`,output:`14`,hint:`Сначала найдём книги на трёх полках, затем добавим отдельные книги.`}),(0,b.jsxs)(`p`,{children:[`Сначала предположим вывод и объясним, почему ответ измеряется в книгах. На экране Python покажет только`,(0,b.jsx)(`code`,{children:`14`}),`: слово «книг» добавляет человек, который объясняет результат.`]}),(0,b.jsx)(`p`,{children:`Попробуем изменить только один вход: отдельных книг стало пять вместо двух. Число полок и книг на каждой осталось прежним, значит первая часть выражения по-прежнему даёт двенадцать. Меняется только прибавляемое количество, и итог становится семнадцать. Если же выросло число полок, изменится результат умножения. Такая проверка помогает увидеть, что формула работает с исходными значениями. Написанное вручную число 14 не сможет отреагировать на изменение условия.`}),(0,b.jsx)(_,{caption:`Считаем книги на полках и добавляем отдельные книги`,children:(0,b.jsxs)(h,{label:`От трёх полок к общему числу книг`,children:[(0,b.jsx)(p,{title:`Группы`,children:(0,b.jsx)(`p`,{children:`3 полки по 4 книги`})}),(0,b.jsx)(m,{label:`считаем книги на полках`}),(0,b.jsx)(p,{title:`На полках`,children:(0,b.jsx)(`p`,{children:`3 * 4 = 12 книг`})}),(0,b.jsx)(m,{label:`добавляем 2 книги`}),(0,b.jsx)(p,{title:`Всего`,children:(0,b.jsx)(`p`,{children:`12 + 2 = 14 книг`})})]})})]}),(0,b.jsxs)(s,{number:`03`,title:`Обновляем значение, читая прежнее`,children:[(0,b.jsxs)(o,{children:[`В строке `,(0,b.jsx)(`code`,{children:`count = count + 1`}),` Python сначала смотрит на прежнее значение `,(0,b.jsx)(`code`,{children:`count`}),`. Если там было 7, он считает `,(0,b.jsx)(`code`,{children:`7 + 1`}),` и записывает в `,(0,b.jsx)(`code`,{children:`count`}),` новое значение 8. Знак`,(0,b.jsx)(`code`,{children:`=`}),` здесь значит «запиши результат в имя», а не «проверь, равны ли числа».`]}),(0,b.jsxs)(`p`,{children:[`Такое повторное присваивание называют обновлением значения. Само число 7 не превратилось в 8. Python посчитал новое число, а имя `,(0,b.jsx)(`code`,{children:`count`}),` теперь обозначает его. Правая часть вычисляется первой, поэтому имя справа ещё хранит прежнее значение, пока расчёт не закончен.`]}),(0,b.jsx)(`p`,{children:`Представим табло счёта. Было 7 очков, команда заработала ещё 2, и на табло теперь 9. Следующий шаг начинается с этих 9, а не с прежних 7. Так же работает следующее присваивание: оно видит то значение, которое сейчас записано в имени.`}),(0,b.jsxs)(`p`,{children:[`Если в начале `,(0,b.jsx)(`code`,{children:`count`}),` равно 7, то после `,(0,b.jsx)(`code`,{children:`count = count + 2`}),` в нём будет 9. Следующая строка прочитает уже 9 и прибавит 3. Получится 12. Важно не начинать второй шаг снова с 7. Присваивание само ничего не показывает на экране. Чтобы увидеть итог, нужна команда`,(0,b.jsx)(`code`,{children:`print`}),`.`]}),(0,b.jsx)(v,{code:`count = 7
count = count + 2
count = count + 3
print(count)`,steps:[{line:0,note:`Сначала связываем count с исходным целым значением 7.`,vars:{count:`7`}},{line:1,note:`Правая часть читает 7, вычисляет 7 + 2 и затем обновляет имя до 9.`,vars:{count:`9`}},{line:2,note:`Теперь правая часть читает 9, вычисляет 9 + 3 и обновляет имя до 12.`,vars:{count:`12`}},{line:3,note:`Команда вывода читает текущее значение имени и показывает 12.`,vars:{count:`12`}}]}),(0,b.jsx)(`p`,{children:`Проследим значение после каждой строки: 7 станет 9, затем 12. Второе обновление начинается с 9, а не с исходных 7. На каждом шаге проверим, что считает правая часть и какое значение запишется в имя: так проще найти строку, которая дала неожиданный итог.`})]}),(0,b.jsxs)(s,{number:`04`,title:`Выбираем деление по нужному ответу`,children:[(0,b.jsx)(`p`,{children:`Перед выбором знака сформулируем вопрос словами. «Сколько приходится на одну часть?» допускает дробный ответ. «Сколько групп заполнено полностью?» требует число полных групп. «Что осталось после них?» спрашивает о предметах, которые в группы не попали. Все три вопроса могут относиться к тем же исходным числам. Поэтому одинаковые данные ещё не означают одинаковую формулу. Важен смысл результата, который просит условие.`}),(0,b.jsx)(o,{children:`Возьмём 73 минуты и размер часа 60 минут. Можно узнать долю часа, число полных часов или оставшиеся минуты. Число, на которое делим, называют делителем. Сначала выбираем вопрос, затем знак деления.`}),(0,b.jsx)(t,{rows:[[`a / b`,`Обычное деление сохраняет дробную часть. Его результат имеет тип float.`],[`a // b`,`Для неотрицательного количества показывает, сколько полных групп получилось.`],[`a % b`,`Показывает, сколько единиц осталось после полных групп.`]]}),(0,b.jsxs)(`p`,{children:[`Если нужна доля часа, берём `,(0,b.jsx)(`code`,{children:`/`}),`: `,(0,b.jsx)(`code`,{children:`73 / 60`}),` даёт примерно `,(0,b.jsx)(`code`,{children:`1.216`}),` часа. Результат имеет тип `,(0,b.jsx)(`code`,{children:`float`}),`, даже когда деление целое: `,(0,b.jsx)(`code`,{children:`60 / 60`}),` даёт `,(0,b.jsx)(`code`,{children:`1.0`}),`. Десятичная часть показывает долю часа, а не дополнительные минуты. Точность таких значений разберём позже.`]}),(0,b.jsxs)(_,{caption:`Три вопроса к 73 минутам и размеру часа в 60 минут`,children:[(0,b.jsxs)(h,{label:`Путь от минут к частному с дробной частью`,children:[(0,b.jsx)(p,{title:`Дано`,children:(0,b.jsx)(`p`,{children:`73 минуты и 60 минут в часе`})}),(0,b.jsx)(m,{label:`сохраняем дробную часть`}),(0,b.jsx)(p,{title:`Оператор /`,children:(0,b.jsx)(`p`,{children:`73 / 60 = 1.216... часа, результат float`})})]}),(0,b.jsxs)(h,{label:`Путь от минут к полным часам`,children:[(0,b.jsx)(p,{title:`Дано`,children:(0,b.jsx)(`p`,{children:`73 минуты и 60 минут в часе`})}),(0,b.jsx)(m,{label:`считаем полные группы`}),(0,b.jsx)(p,{title:`Оператор //`,children:(0,b.jsx)(`p`,{children:`73 // 60 = 1 полный час`})})]}),(0,b.jsxs)(h,{label:`Путь от минут к оставшимся минутам`,children:[(0,b.jsx)(p,{title:`Дано`,children:(0,b.jsx)(`p`,{children:`73 минуты и 60 минут в часе`})}),(0,b.jsx)(m,{label:`находим остаток`}),(0,b.jsx)(p,{title:`Оператор %`,children:(0,b.jsx)(`p`,{children:`73 % 60 = 13 минут`})})]})]}),(0,b.jsxs)(`p`,{children:[`Это не цепочка действий: каждый оператор отвечает на свой вопрос. Проверка связывает целые часы и остаток:`,(0,b.jsx)(`code`,{children:`1 * 60 + 13 = 73`}),`. Для неотрицательных количеств остаток меньше размера группы; единицы помогают отличить часы от минут.`]}),(0,b.jsx)(c,{statement:(0,b.jsxs)(b.Fragment,{children:[`В Python `,(0,b.jsx)(`code`,{children:`%`}),` означает «найти процент».`]}),isTrue:!1,explanation:`Здесь % возвращает остаток: после одного полного часа остаются 13 минут. Это не процент от числа.`}),(0,b.jsx)(_,{caption:`17 булочек: три полные коробки и две отдельно`,children:(0,b.jsxs)(h,{label:`Раскладываем 17 булочек по 5`,children:[(0,b.jsx)(p,{title:`В наличии`,children:(0,b.jsx)(`p`,{children:`17 булочек`})}),(0,b.jsx)(m,{label:`кладём по 5`}),(0,b.jsxs)(p,{title:`3 полные коробки`,children:[(0,b.jsx)(`p`,{children:`[ ● ● ● ● ● ]`}),(0,b.jsx)(`p`,{children:`[ ● ● ● ● ● ]`}),(0,b.jsx)(`p`,{children:`[ ● ● ● ● ● ]`})]}),(0,b.jsx)(m,{label:`остаётся отдельно`}),(0,b.jsx)(p,{title:`2 булочки вне коробок`,children:(0,b.jsx)(`p`,{children:`○ ○`})})]})}),(0,b.jsx)(d,{question:`В коробку входит по 5 булочек. Какой оператор найдёт число полных коробок из 17 булочек?`,options:[`17 / 5`,`17 % 5`,`17 // 5`],correctIndex:2,explanation:`17 // 5 даёт 3 полные коробки, а 17 % 5 даёт 2 оставшиеся булочки. Проверка 3 * 5 + 2 = 17 восстанавливает исходное количество.`}),(0,b.jsx)(`p`,{children:`Проверим рисунок без новой формулы: в трёх коробках по пять лежат пятнадцать булочек. Две остались снаружи. Почему нельзя заполнить ещё одну коробку? Для неё нужно пять, а у нас только две. Значит остаток меньше размера группы. У минут устроено так же: после выделения полных часов остаётся меньше шестидесяти минут. Число полных групп измеряется в коробках или часах, а остаток сохраняет исходную единицу: булочки или минуты. Подпишем эти ответы до вывода, чтобы не поменять их местами.`}),(0,b.jsx)(`p`,{children:`Теперь мысленно положим в коробки пятнадцать булочек, затем шестнадцать и семнадцать. Во всех трёх случаях полных коробок останется три, а остаток изменится: ноль, один, два. Когда будет двадцать, полных коробок станет четыре и остаток снова окажется нулём. Так можно проверить правило на границе: число групп меняется только после заполнения следующей группы. В практике проверка использует такие соседние случаи, чтобы заметить случайно перепутанные операторы.`})]}),(0,b.jsxs)(s,{number:`05`,title:`Проверяем границы знакомого правила`,children:[(0,b.jsx)(`p`,{children:`Проверять формулу удобно до запуска. Подставим в неё маленькие числа, которые легко посчитать устно. Ноль предметов даёт ноль полных групп и нулевой остаток. Когда предметов ровно столько, сколько входит в группу, получается одна полная группа без остатка. На один предмет больше означает ту же одну группу и один оставшийся предмет. Это три разных состояния правила, а не три новые формулы. После такой проверки вернём имена исходных данных: программа должна сама получать ответы для каждого набора.`}),(0,b.jsx)(`p`,{children:`Если полные группы и остаток не восстанавливают исходное количество, сверим роли чисел. Размер группы должен оставаться одинаковым в обоих вычислениях. Ошибка имени может дать допустимую арифметику, но описывать уже совсем другое распределение предметов.`}),(0,b.jsxs)(`p`,{children:[`История с коробками удобна, если предметов ноль или больше, а размер коробки больше нуля. Тогда`,(0,b.jsx)(`code`,{children:`//`}),` показывает полные коробки, а `,(0,b.jsx)(`code`,{children:`%`}),` показывает оставшиеся предметы. С отрицательными числами бытовая история перестаёт помогать: отрицательного количества коробок не бывает.`]}),(0,b.jsxs)(r,{tone:`info`,children:[(0,b.jsx)(`strong`,{children:`Дополнительно, это не понадобится для основной практики.`}),` Для отрицательных чисел`,(0,b.jsx)(`code`,{children:`//`}),` округляет вниз, к меньшему целому, а не к ближайшему числу и не к нулю. Например,`,(0,b.jsx)(`code`,{children:`-7 / 3`}),` находится между -2 и -3. На числовой прямой -3 левее и меньше, поэтому`,(0,b.jsx)(`code`,{children:`-7 // 3`}),` равно -3. Остаток равен 2: `,(0,b.jsx)(`code`,{children:`-7 = -3 * 3 + 2`}),`. Здесь 2 не означает два предмета в коробке, это результат правила Python.`]}),(0,b.jsx)(`p`,{children:`Этот пример показывает границу модели. В упражнениях мы будем считать обычные количества предметов: от нуля и выше, с коробкой известного размера.`}),(0,b.jsxs)(`p`,{children:[`Отрицательное значение иногда нужно само по себе. Например, отклонение от плана может быть минус три. Если интересует только величина отклонения, готовая функция `,(0,b.jsx)(`code`,{children:`abs`}),` возвращает расстояние до нуля:`,(0,b.jsx)(`code`,{children:`abs(-3)`}),` даёт 3, `,(0,b.jsx)(`code`,{children:`abs(3)`}),` тоже даёт 3, а `,(0,b.jsx)(`code`,{children:`abs(0)`}),` даёт 0. Это отдельный вопрос, а не исправление любого отрицательного ответа. Если знак показывает долг или направление, его удаление потеряет нужную информацию. Сначала читаем смысл задачи, затем выбираем операцию.`]}),(0,b.jsx)(y,{caption:`Величина отклонения от нуля`,code:`difference = -3
distance = abs(difference)
print(difference)
print(distance)`}),(0,b.jsx)(`p`,{children:`Получим две строки: -3 и 3. Вызов abs не изменил исходное значение difference. Другое имя хранит ответ на вопрос о расстоянии. Такой короткий опыт помогает отделить получение нового результата от изменения старого имени, как мы уже делали со строками.`}),(0,b.jsxs)(`p`,{children:[`На ноль делить нельзя. Если после знака деления стоит 0, Python сообщает об ошибке`,(0,b.jsx)(`code`,{children:`ZeroDivisionError`}),` и останавливает этот расчёт. Пока нам достаточно заметить ноль и понять, почему программа остановилась.`]}),(0,b.jsx)(n,{code:`minutes = 60
hours = minutes // 0
print(hours)`,question:`Почему Python не доходит до вывода результата?`,options:[`Python не умеет делить целые числа.`,`После знака деления стоит 0, а на ноль делить нельзя.`,`60 минут слишком много для расчёта часов.`],correctIndex:1,explanation:`После // стоит делитель, то есть число, на которое мы делим. Здесь это 0. Поставьте размер часа 60, и расчёт сможет продолжиться.`,fix:`minutes = 60
hours = minutes // 60
print(hours)`}),(0,b.jsxs)(`p`,{children:[`Ошибка возникает на строке с делением, поэтому следующая команда `,(0,b.jsx)(`code`,{children:`print`}),` не запускается. Значение 60 подходит для расчёта минут в часах. Проблема в том, что справа от `,(0,b.jsx)(`code`,{children:`//`}),` стоит ноль. При такой ошибке сначала проверим число, на которое делим.`]}),(0,b.jsxs)(r,{children:[`Перед делением проверим второе число. Для перевода минут в часы это 60. Ноль в этой позиции вызывает`,(0,b.jsx)(`code`,{children:`ZeroDivisionError`}),`.`]})]}),(0,b.jsxs)(s,{number:`06`,title:`Что мы будем делать в практике`,children:[(0,b.jsx)(o,{children:`В каждом задании числа уже подготовлены, вводить их не нужно. Мы запишем короткую программу и покажем ответы на экране. Автопроверка подставит другие числа: так мы убедимся, что программа считает по правилу, а не выводит один заранее угаданный ответ.`}),(0,b.jsx)(f,{variant:`connected`,items:[{title:`Составим и обновим`,description:`Посчитаем предметы в наборах, добавим отдельные, а потом дважды прибавим по одному.`},{title:`Сравним деление`,description:`Посмотрим, что показывают /, // и % для 0, 59, 60 и 61 минуты.`},{title:`Перенесём правило`,description:`Переложим новые количества предметов в одинаковые коробки и найдём остаток.`}]}),(0,b.jsx)(`p`,{children:`Если запутаемся, вернёмся к нужной части: сначала единицы и скобки, затем обновление имени, потом три способа деления. Проверка сама подставит числа и сравнит вывод программы с ожидаемым.`}),(0,b.jsx)(`p`,{children:`В конце мы сможем объяснить, что посчитали, почему выбрали этот знак и в каких единицах получился ответ. Эти навыки пригодятся на следующем занятии, где мы будем работать с числами с дробной частью.`})]})]})}export{x as Lesson03};